parameters.jsCode:
// This forces the response to be an ARRAY, which fixed the .map() error
return [
  {
    json: {
      "job_id": $input.first().json.job_id,
      "skills_list": $input.first().json.analysis_json.skills.required,
      "experience_list": $input.first().json.analysis_json.experience.key_responsibilities,
      "education_list": $input.first().json.analysis_json.education.fields_of_study,
      "certifications_list": $input.first().json.analysis_json.certifications,
      ""
      // ... include any other fields you need here
    }
  }
];

// --- Read data directly from nodes (wiring-safe) ---
const meta = $('Get Job Meta data').first().json;
const jobDetails = $('Get job details').first().json; // contains analysis_json (and anything else you already relied on)
const apply = $('Job apply method').first().json;

// --- Read application stats (Postgres node you added) ---
const stats = $('Get Job Applications Stats').first()?.json || {};

// helper
const toNum = (v, d = 0) => {
  const n = typeof v === 'number' ? v : parseInt(String(v ?? ''), 10);
  return Number.isFinite(n) ? n : d;
};

// Dashboard-style counters (what the new frontend shows)
const applications_total     = toNum(stats.applications_total, 0);
const applications_qualified = toNum(stats.applications_qualified, 0);
const applications_partial   = toNum(stats.applications_partial, 0);
const applications_rejected  = toNum(stats.applications_rejected, 0);

// Keep the old fields too (won’t hurt, and keeps backward compatibility)
const applications_above_threshold = applications_qualified + applications_partial;
const applications_below_threshold = applications_rejected;
const applications_recommended     = applications_qualified;

return [
  {
    json: {
      details: {
        job_id: meta.job_id,
        job_code: meta.job_code,     // useful for FE / consistency
        Job_Code: meta.job_code,     // keep old field (if anything still uses it)

        job_status: meta.status,
        job_title: meta.job_title,
        job_client: meta.job_client,
        job_type: meta.job_type,
        location: meta.job_location,

        posted_date: (() => {
          const v = meta.created_at;
          return v ? String(v).split('T')[0] : null;
        })(),
        closing_date: (() => {
          const v = meta.end_date;
          return v ? String(v).split('T')[0] : null;
        })(),

        // ✅ NEW: what JobDetails (2).tsx KPIs expect
        applications_total,
        applications_qualified,
        applications_partial,
        applications_rejected,

        // ✅ Keep existing fields (no harm, may be used elsewhere)
        applications_above_threshold,
        applications_below_threshold,
        applications_recommended,

        ingestion_note: apply.ingestion_note,
        description: meta.job_description,
      },

      // FE does: analysis_json: payload.analysis
      analysis: jobDetails.analysis_json ?? $input.first()?.json?.analysis_json,
    },
  },
];

const meta = $('Get Job Meta data').first().json;

const ingestionModeRaw = (meta.cv_ingestion_node || '').toString().trim().toLowerCase();
const ingestionMode =
  ingestionModeRaw === 'forwarding' ? 'forward' : ingestionModeRaw; // normalize

const platformEmail = meta.platform_email || null;
const jobCode = meta.job_code || meta.job_id || '';

const FORWARD_EMAIL = 'jobs@ai970.cloud';

let ingestion_email = null;
let ingestion_note = '';

if (ingestionMode === 'forward') {
  ingestion_email = null;
  ingestion_note =
    `CVs for this job must be forwarded to ${FORWARD_EMAIL}. ` +
    (jobCode
      ? `Please include the job reference (${jobCode}) in the email subject or body to ensure correct routing.`
      : `Please include the job reference in the email subject or body to ensure correct routing.`);

} else if (ingestionMode === 'platform_email') {
  ingestion_email = platformEmail;
  ingestion_note = platformEmail
    ? `Applicants must send their CVs directly to ${platformEmail}.`
    : `Applicants must send their CVs to the designated platform email address.`;

} else {
  // fallback: still return something useful
  ingestion_email = platformEmail;
  ingestion_note =
    `CV submission method is not clearly configured. Please contact support or verify the job ingestion settings.`;
}

return [
  {
    json: {
      ingestion_mode: ingestionModeRaw,   // keep original value for FE (forwarding/platform_email)
      ingestion_email,
      ingestion_note,
    },
  },
];
